/**
 * Hides nav items the actor cannot access.
 *
 * Owner B implements `@/components/domain/nav/app-sidebar`. The filtering rule
 * itself is covered by `tests/config/nav.test.ts`; these assert the rendering.
 */
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

// AppSidebar renders `OrgSwitcher`, a client component that calls
// `useRouter()` from `next/navigation`; jsdom has no app-router context, so
// the hook is stubbed the way the app's own router provider would supply it.
vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), refresh: vi.fn() }),
}));

import { AppSidebar } from "@/components/domain/nav/app-sidebar";
import { SIDEBAR_NAV, visibleNav } from "@/config/nav";
import { orgPath, projectPath } from "@/lib/url";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import { makeActor, makeOrganization, makeProject } from "../helpers/factories";

afterEach(cleanup);

const NO_FLAGS: FeatureFlagSnapshot = {
  kanban_board: false,
  ai_issue_summary: false,
  command_palette: false,
  activity_feed: false,
  public_projects: false,
  webhooks: false,
  csv_export: false,
  digest_email: false,
  issue_templates: false,
  advanced_search: false,
};

const ALL_FLAGS: FeatureFlagSnapshot = {
  ...NO_FLAGS,
  kanban_board: true,
  activity_feed: true,
  advanced_search: true,
};

describe("components/app-sidebar", () => {
  // The sidebar renders exactly the labels visibleNav() returns for the actor.
  it("renders one link per visible nav item", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={ALL_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    const expected = visibleNav(SIDEBAR_NAV, actor, ALL_FLAGS);
    for (const item of expected) {
      expect(screen.getAllByRole("link", { name: item.label }).length).toBeGreaterThan(0);
    }
  });

  // A viewer's sidebar has no Activity link, because activity:read is member+.
  it("omits a nav item the actor lacks the permission for", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "viewer", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={ALL_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    expect(screen.queryByRole("link", { name: "Activity" })).not.toBeInTheDocument();
  });

  // With the kanban_board flag off, the Board child link is absent.
  it("omits a nav item whose flag is off in the snapshot", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={NO_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    expect(screen.queryByRole("link", { name: "Board" })).not.toBeInTheDocument();
  });

  // Child items render nested under their parent.
  it("nests child items under their parent", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={ALL_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    const issuesLink = screen.getByRole("link", { name: "Issues" });
    const parentItem = issuesLink.closest("li");
    expect(parentItem).not.toBeNull();

    const childLink = screen.getByRole("link", { name: "Assigned to me" });
    // The child link lives inside the parent <li>, not as a sibling of it.
    expect(parentItem).toContainElement(childLink);
  });

  // hrefs come from @/lib/url, not from string concatenation in the component.
  it("builds hrefs through the url helpers", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });
    const project = makeProject({ orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={ALL_FLAGS}
        projects={[project]}
        pathname="/acme"
      />,
    );

    expect(screen.getByRole("link", { name: "Overview" })).toHaveAttribute(
      "href",
      orgPath(org.slug, ""),
    );
    expect(screen.getByRole("link", { name: project.name })).toHaveAttribute(
      "href",
      projectPath(org.slug, project.slug),
    );
  });
});
/** `visibleNav` filters by permission and by flag. */
import { describe, expect, it } from "vitest";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav } from "@/config/nav";
import { snapshotFlags } from "@/lib/feature-flags";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { PlanId } from "@/types/billing";
import type { Role } from "@/types/member";
import { ALICE, ORG_A, makeActor } from "../helpers/factories";

function flagsFor(plan: PlanId, role: Role): FeatureFlagSnapshot {
  return snapshotFlags({ orgId: ORG_A, userId: ALICE, plan, role });
}

function keysOf(items: readonly { key: string }[]): readonly string[] {
  return items.map((item) => item.key);
}

describe("config/nav", () => {
  it("declares a permission for every nav entry", () => {
    for (const item of [...SIDEBAR_NAV, ...SETTINGS_NAV]) {
      expect(item.action, item.key).toBeDefined();
      expect(item.key).not.toBe("");
    }
  });

  it("shows an owner on an enterprise plan the full sidebar", () => {
    const visible = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("enterprise", "owner"),
    );
    expect(keysOf(visible)).toEqual(keysOf(SIDEBAR_NAV));
  });

  it("hides the activity feed from a viewer, who lacks activity:read", () => {
    const visible = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "viewer" }),
      flagsFor("enterprise", "viewer"),
    );
    expect(keysOf(visible)).not.toContain("activity");
    expect(keysOf(visible)).toContain("overview");
  });

  it("hides a flagged entry when the plan does not include the flag", () => {
    const free = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("free", "owner"),
    );
    expect(keysOf(free)).not.toContain("activity");

    const growth = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("growth", "owner"),
    );
    expect(keysOf(growth)).toContain("activity");
  });

/** Route shapes and query-string composition. */
import { describe, expect, it } from "vitest";
import {
  issuePath,
  orgPath,
  projectPath,
  settingsPath,
  withSearchParams,
} from "@/lib/url";

describe("lib/url", () => {
  it("builds an org-rooted path", () => {
    expect(orgPath("acme")).toBe("/acme");
    expect(orgPath("acme", "issues")).toBe("/acme/issues");
    expect(orgPath("acme", "issues", "new")).toBe("/acme/issues/new");
  });

  it("encodes segments so a slug cannot break out of the path", () => {
    expect(orgPath("acme corp")).toBe("/acme%20corp");
    expect(orgPath("acme", "a/b")).toBe("/acme/a%2Fb");
  });

  it("nests project paths under the org", () => {
    expect(projectPath("acme", "website")).toBe("/acme/projects/website");
    expect(projectPath("acme", "website", "board")).toBe(
      "/acme/projects/website/board",
    );
  });

  it("builds an issue path from the issue number", () => {
    expect(issuePath("acme", "website", 142)).toBe(
      "/acme/projects/website/issues/142",
    );
  });

  it("builds settings paths with and without a section", () => {
    expect(settingsPath("acme")).toBe("/acme/settings");
    expect(settingsPath("acme", "billing")).toBe("/acme/settings/billing");
  });

  it("appends query parameters and stringifies numbers", () => {
    expect(withSearchParams("/acme/issues", { status: "todo", page: 2 })).toBe(
      "/acme/issues?status=todo&page=2",
    );
  });

  it("drops undefined parameters instead of writing 'undefined'", () => {
    expect(withSearchParams("/acme/issues", { status: undefined })).toBe(
      "/acme/issues",
    );
  });

  it("merges into an existing query string, overwriting on conflict", () => {
    expect(withSearchParams("/acme/issues?status=done&page=1", { page: 3 })).toBe(
      "/acme/issues?status=done&page=3",
    );
  });

  it("removes a parameter when its value is undefined", () => {
    expect(withSearchParams("/acme/issues?status=done", { status: undefined })).toBe(
      "/acme/issues",
    );
  });
});

