}

export function isDueBeforeValue(raw: unknown): raw is string {
  return parseDueBefore(raw) !== null;
}

/**
 * The instant an issue must be due strictly before to match `due_before`.
 *
 * - A calendar date is read in UTC and includes the whole day, so the bound
 *   is midnight at the start of the *next* day.
 * - A full timestamp is its own bound.
 *
 * Returned in the canonical millisecond `…Z` form; `null` for a value that is
 * not part of the vocabulary.
 */
export function dueBeforeExclusiveBound(raw: unknown): IsoTimestamp | null {
  const parsed = parseDueBefore(raw);
  if (parsed === null) return null;

  if (parsed.kind === "date") {
    const [year, month, day] = parsed.value.split("-").map(Number) as [
      number,
      number,
      number,
    ];
    const midnight = utcMidnight(year, month, day);
    if (midnight === null) return null;
    return new Date(midnight + MS_PER_DAY).toISOString() as IsoTimestamp;
  }

  return new Date(parsed.value).toISOString() as IsoTimestamp;
}

