/** How a filter treats archived issues. */
export type ArchiveMode = "live" | "all" | "only";

export function archiveModeOf(
  includeArchived: boolean | ArchivedOnly | null | undefined,
): ArchiveMode {
  if (includeArchived === ARCHIVED_ONLY) return "only";
  return includeArchived === true ? "all" : "live";
}

/* ------------------------------------------------------- assignee / author */

export function isMeToken(value: unknown): value is MeToken {
  return value === ME_TOKEN;
}

/** Resolves `me` against the acting user; every other value is returned as is. */
export function resolveMe<T>(value: T, actingUserId: UserId): Exclude<T, MeToken> | UserId {
  return isMeToken(value) ? actingUserId : (value as Exclude<T, MeToken>);
}
