 * `due_at` normalised to the canonical millisecond `…Z` spelling, so the
 * comparison is between instants however the stored timestamp was written
 * (`…:00Z` and `…:00.000Z` are the same instant but not the same text).
 * `NULL` for an issue without a due date, which therefore never matches.
 */
const DUE_AT_INSTANT = sql<
  string | null
>`strftime('%Y-%m-%dT%H:%M:%fZ', ${issues.dueAt})`;

/**
 * The archive predicate for one of the three scopes of the filter vocabulary:
 * live issues only (the default), archived alongside live, archived only.
 */
function archivePredicate(input: IssueFilterInput): SQL | undefined {
  if (archiveModeOf(input.includeArchived) === "only") {
    return isNotNull(issues.archivedAt);
  }
  const scope: ArchiveScope = shouldFilterArchived({
    includeArchived: input.includeArchived === true,
  })
    ? {}
    : { includeArchived: true };
  return livePredicate(issues.archivedAt, scope);
}

/** A user id narrows to that user, `null` (or `none`) to unassigned issues. */
function assigneePredicate(
  assigneeId: IssueFilterInput["assigneeId"] | typeof UNASSIGNED_TOKEN,
): SQL | undefined {
  if (assigneeId === undefined) return undefined;
  if (assigneeId === null || assigneeId === UNASSIGNED_TOKEN) {
    return isNull(issues.assigneeId);
  }
  return eq(issues.assigneeId, concreteUser("assigneeId", assigneeId));
}

/**
 * `me` means the acting user, and a repository has no actor: the service
 * resolves it before the filter gets here. Comparing the column with the
 * literal text would silently list nothing, so an unresolved `me` is an error.
 */
function concreteUser(field: string, value: UserId | MeToken): UserId {
  if (isMeToken(value)) {
    throw new Error(
      `Issue filter ${field}="me" must be resolved to the acting user before it reaches the repository`,
    );
  }
  return value;
}

/**
 * All-of: the issues that carry every one of `labelIds`. Counting distinct
 * matches per issue against the number of distinct labels asked for keeps it
 * one predicate, shared by the page query and its count.
 */
function labelsPredicate(
  orgId: OrgId,
  labelIds: readonly LabelId[] | undefined,
): SQL | undefined {
  const wanted = [...new Set(labelIds ?? [])];
  if (wanted.length === 0) return undefined;

  return inArray(
    issues.id,
    getDb()
      .select({ id: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.labelId, wanted),
        ),
      )
