/** Any-of over concrete statuses, after expanding `open` / `closed`. */
function statusPredicate(
  status: IssueFilterInput["status"],
): SQL | undefined {
  if (status === undefined || status.length === 0) return undefined;
  const statuses = expandIssueStatuses(status);
