/**
 * A calendar date includes its whole day (UTC); a full timestamp is a strict
 * upper bound. Either way the issue must be due before one exclusive instant.
 */
function dueBeforePredicate(
  dueBefore: IssueFilterInput["dueBefore"],
): SQL | undefined {
  if (dueBefore === undefined) return undefined;
  const bound = dueBeforeExclusiveBound(dueBefore);
  if (bound === null) {
    throw new Error(
      `Issue filter dueBefore must be a YYYY-MM-DD date or an ISO-8601 timestamp, got "${String(dueBefore)}"`,
