mkdir -p /tmp/tf-scratch && P="$PWD" && cat > /tmp/tf-scratch/vitest.config.mjs <<EOF
import { defineConfig } from "$P/node_modules/vitest/dist/config.js";
export default defineConfig({
  root: "$P",
  resolve: { alias: { "@": "$P/src", "~t": "$P/tests" } },
  server: { fs: { strict: false } },
  test: { environment: "node", globals: true, include: ["/tmp/tf-scratch/*.test.ts"], dir: "/tmp/tf-scratch" },
});
EOF
cat > /tmp/tf-scratch/filters.test.ts <<'EOF'
vi.mock("@/lib/id", () => import("~t/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("~t/server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { issueFilterSchema } from "@/schemas/issue";
import { exportIssuesSchema } from "@/schemas/export";
import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { orgHref } from "@/lib/url";
import { createTenant, issueInput, useTemporaryDatabase } from "~t/server/_support/fixtures";

let cleanup: () => void;
let t: any;
const ids: Record<string, string> = {};
let L1: any, L2: any;

async function mk(title: string, o: any = {}) {
  const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const issue = await issueRepo.insertIssue(
    { ...issueInput(t.org.id, t.project.id, { title, assigneeId: o.assigneeId ?? null, dueAt: o.dueAt ?? null }), status: o.status ?? "backlog", labelIds: o.labelIds ?? [] } as any,
    o.author ?? t.userIds.owner, number);
  ids[title] = issue.id;
  if (o.archived) await issueRepo.archiveIssue(t.org.id, issue.id);
  return issue;
}

async function run(qs: string, actor = t.actors.member) {
  const filter = parseIssueFilterParams(new URLSearchParams(qs));
  const parsed = issueFilterSchema.parse({ ...filter, orgId: t.org.id, limit: 100 });
  const page = await issueService.listIssues(actor, parsed);
  const titles = page.items.map((i) => i.title).sort();
  expect(page.total).toBe(titles.length);
  return titles;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratch");
  L1 = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ef4444", description: null });
  L2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#ef4444", description: null });
  await mk("a-mine-todo", { assigneeId: t.userIds.member, status: "todo", labelIds: [L1.id, L2.id], dueAt: "2026-03-02T00:00:00.000Z" });
  await mk("b-unassigned-done", { status: "done", labelIds: [L1.id], dueAt: "2026-03-02T23:59:59Z" });
  await mk("c-admin-review", { assigneeId: t.userIds.admin, status: "in_review", labelIds: [L2.id], dueAt: "2026-03-03T00:00:00Z" });
  await mk("d-archived-canceled", { status: "canceled", archived: true, author: t.userIds.member, dueAt: "2026-03-01T12:00:00Z" });
  await mk("e-nodue-progress", { status: "in_progress", assigneeId: t.userIds.member });
});
afterAll(() => cleanup());

it("filters", async () => {
  expect(await run("")).toEqual(["a-mine-todo", "b-unassigned-done", "c-admin-review", "e-nodue-progress"]);
  expect(await run("assignee=me")).toEqual(["a-mine-todo", "e-nodue-progress"]);
  expect(await run("assignee=me", t.actors.admin)).toEqual(["c-admin-review"]);
  expect(await run("assignee=none")).toEqual(["b-unassigned-done"]);
  expect(await run("author=me&archived=1")).toEqual(["d-archived-canceled"]);
  expect(await run(`label=${L1.id},${L2.id}`)).toEqual(["a-mine-todo"]);
  expect(await run(`label=${L1.id},${L1.id}`)).toEqual(["a-mine-todo", "b-unassigned-done"]);
  expect(await run("status=open")).toEqual(["a-mine-todo", "c-admin-review", "e-nodue-progress"]);
  expect(await run("status=closed")).toEqual(["b-unassigned-done"]);
  expect(await run("status=closed&archived=1")).toEqual(["b-unassigned-done", "d-archived-canceled"]);
  expect(await run("status=closed,todo")).toEqual(["a-mine-todo", "b-unassigned-done"]);
  expect(await run("archived=only")).toEqual(["d-archived-canceled"]);
  expect(await run("due_before=2026-03-02")).toEqual(["a-mine-todo", "b-unassigned-done"]);
  expect(await run("due_before=2026-03-02&archived=1")).toEqual(["a-mine-todo", "b-unassigned-done", "d-archived-canceled"]);
  expect(await run("due_before=2026-03-02T00:00:00Z")).toEqual([]);
  expect(await run("due_before=2026-03-02T00:00:00.001Z")).toEqual(["a-mine-todo"]);
  expect(await run("due_before=2026-03-03T00:00:00.000Z")).toEqual(["a-mine-todo", "b-unassigned-done"]);
  expect(await run("due_before=2026-03-03")).toEqual(["a-mine-todo", "b-unassigned-done", "c-admin-review"]);
  expect(await run("due_before=garbage&status=nonsense")).toHaveLength(4);
});

it("schema & repo accept raw vocabulary", async () => {
  const ok = (x: any) => issueFilterSchema.safeParse({ orgId: t.org.id, ...x }).success;
  expect(ok({ status: ["open", "done"] })).toBe(true);
  expect(ok({ status: ["nonsense"] })).toBe(false);
  expect(ok({ assigneeId: "me", authorId: "me" })).toBe(true);
  expect(ok({ assigneeId: "none" })).toBe(true);
  expect(ok({ authorId: "none" })).toBe(false);
  expect(ok({ dueBefore: "2026-03-02" })).toBe(true);
  expect(ok({ dueBefore: "2026-02-30" })).toBe(false);
  expect(ok({ dueBefore: "2026-03-02T10:00:00Z" })).toBe(true);
  expect(ok({ dueBefore: "2026-03-02T10:00:00" })).toBe(false);
  expect(ok({ dueBefore: "tomorrow" })).toBe(false);
  expect(ok({ includeArchived: "only" })).toBe(true);
  expect(ok({ includeArchived: "yes" })).toBe(false);
  expect(issueFilterSchema.parse({ orgId: t.org.id, assigneeId: "me" }).assigneeId).toBe("me");
  const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 100, status: ["open"], includeArchived: "only" } as any);
  expect(page.items).toEqual([]);
  const p2 = await issueRepo.listIssues({ orgId: t.org.id, limit: 1, status: ["closed"], includeArchived: true });
  expect(p2.total).toBe(2); expect(p2.items).toHaveLength(1);
  expect(exportIssuesSchema.parse({ orgId: t.org.id, status: ["open"], includeArchived: "true" })).toMatchObject({ status: ["open"], includeArchived: true, format: "csv" });
  expect(exportIssuesSchema.parse({ orgId: t.org.id }).includeArchived).toBe(false);
});

it("codec", () => {
  const p = (q: string) => parseIssueFilterParams(new URLSearchParams(q));
  expect(p("status=open").status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
  expect(p("status=closed,done,x").status).toEqual(["done", "canceled"]);
  expect(p("assignee=me&author=me")).toEqual({ assigneeId: "me", authorId: "me" });
  expect(issueFilterToParams(p("assignee=me&archived=only&due_before=2026-03-02"))).toEqual({ assignee: "me", archived: "only", due_before: "2026-03-02" });
  expect(p("due_before=nope")).toEqual({});
  expect(orgHref("acme", "issues?assignee=me")).toBe("/acme/issues?assignee=me");
  expect(orgHref("acme", "")).toBe("/acme");
});
EOF
npx vitest run --config /tmp/tf-scratch/vitest.config.mjs 2>&1 | grep -v "npm warn" | tail -40

